    /// <summary>
    /// Lists all defined settings stored in the configuration database.
    /// </summary>
    /// <returns>0 on success, 1 on failure.</returns>
    [Command("list-props", "List defined settings in configuration database.")]
    public static int ListProps()
    {
        try
        {
            var b = CreateAndSetupBuilder([]);
            foreach (var kv in Bovis.Storage.Storage.DefaultStorage.ListProperties())
            {
                Console.WriteLine($"BCBD448ACD8I | {kv.Key,-40} | {Logging.Logger.Redact(kv.Value)}");
            }
            return 0;

        }
        catch (Exception ex)
        {
            MessageDb.ShowException(ex);
            return 1;
        }
    }

    /// <summary>
    /// Sets a property in the configuration database.
    /// </summary>
    /// <param name="name">Name of the property to set.</param>
    /// <param name="value">New value for the property.</param>
    /// <returns>0 on success, 1 on failure.</returns>
    [Command("set-prop", "Set property in configuration database.")]
    public static int SetProp(
            [Option("--name", "Name of property")] string name,
            [Option("--value", "New value of property")] string value)
    {
        try
        {
            var b = CreateAndSetupBuilder([]);
            Bovis.Storage.Storage.DefaultStorage.SetProperty(name, value);

            return 0;

        }
        catch (Exception ex)
        {
            MessageDb.ShowException(ex);
            return 1;
        }
    }

